local KTool = CS.Engine.Lib.KTool

--- from: Assets/BundleResources/Prefabs/ActivityMountain/11300302/ActivityMountainMainLineDialog.prefab > name: ActCSMainLineNode4
---@class ActivityMountainMainLineNode
---@field Env                           	ActivityMountainMainLineNode            
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field Finish                        	UnityEngine.RectTransform               	@ 0    
---@field Normal                        	UnityEngine.RectTransform               	@ 1    
---@field Lock                          	UnityEngine.RectTransform               	@ 2    
---@field TxtName                       	UnityEngine.RectTransform               	@ 3    
---@field TxtTime                       	UnityEngine.RectTransform               	@ 4    
---@field CurrentGroup                  	UnityEngine.RectTransform               	@ 5    
---@field ImgHead                       	UnityEngine.RectTransform               	@ 6    
local ActivityMountainMainLineNode = Class('ActivityMountainMainLineNode')
local ActivityCakeUtils = import('Game.UI.ActivityCakeShopDialog.ActivityCakeUtils')

function ActivityMountainMainLineNode:__init()
	self.delegate = nil
end

function ActivityMountainMainLineNode:__delete()
	self.delegate = nil
end

function ActivityMountainMainLineNode:SetDelegate(_delegate)
	self.delegate = _delegate
end

function ActivityMountainMainLineNode:Awake()
	SetButtonAction(self.controller.gameObject,Bind(self,self.OnBtnNodeClick))
end

function ActivityMountainMainLineNode:OnBtnNodeClick()
	if not self.isPass and not self.isUnLock then
		local time = checkNumber(self.data.unlockCountdown) - os.time()
		if time > 0 then
			GameUtils.Toast(localize("_num_开启",{_num_ = CfUtils.GetTimeHMS11(time)}))
		else
			GameUtils.Toast(localize("请先通关前置关卡"))
		end
		return
	end
	
	local moduleId = self:GetModuleId()
	
	CS.Engine.UI.UIModule.OpenDialog({ id = moduleId, parameters = { questId = self.data.questId,index = self.index }},{{id = self.delegate.controller.Argument.id}})
end

function ActivityMountainMainLineNode:GetModuleId()
	local vo = ActivityCakeUtils.GetChapterPlaceVo(self.data.questId)
	if vo and checkNumber(vo.moduleId) > 0 then
		return vo.moduleId
	end
	return Constants.UITypeIds.ActivityMountainMainLineDetailsDialog
end

function ActivityMountainMainLineNode:RefreshCurrent()
	CfUtils.SetActive(self.CurrentGroup.gameObject,true)
	CfUtils.SetUISwitchImage(self.ImgHead,CfUtils.IsWoman() and 1 or 2)
end

function ActivityMountainMainLineNode:RefreshChapterNodeShow(data,index)
	self.data = data
	self.index = index
	self:SetLockState()
	CfUtils.SetActive(self.CurrentGroup.gameObject,false)
	local vo = ActivityCakeUtils.GetChapterPlaceVo(self.data.questId)
	if not isNull(vo) then
		CfUtils.FillText(self.TxtName,vo.name)
	end
end

function ActivityMountainMainLineNode:SetLockState()
	local isPass = ActivityCakeUtils.GetActivityCakeMgr():IsPassChapterNode(self.data.questId)
	self.isPass = isPass
	if isPass then
		KTool.SetActive(self.Lock.gameObject,false)
		KTool.SetActive(self.Normal.gameObject,true)
		KTool.SetActive(self.Finish.gameObject,true)
	else
		local isUnLock = (checkNumber(self.data.unlockCountdown) - os.time()) <= 0 and ActivityCakeUtils.GetActivityCakeMgr():IsUnLockFirstChapter(self.data.questId)
		self.isUnLock = isUnLock
		if isUnLock then
			KTool.SetActive(self.Lock.gameObject,false)
			KTool.SetActive(self.Normal.gameObject,true)
			KTool.SetActive(self.Finish.gameObject,false)
		else
			KTool.SetActive(self.Lock.gameObject,true)
			KTool.SetActive(self.Normal.gameObject,false)
			KTool.SetActive(self.Finish.gameObject,false)
			self:SetLockParams()
		end
	end
end

function ActivityMountainMainLineNode:SetLockParams()
	local time = checkNumber(self.data.unlockCountdown) - os.time()
	if time > 0 then
		CfUtils.FillText(self.TxtTime,localize("_num_开启",{_num_ = CfUtils.GetTimeHMS11(time)}))
	else
		CfUtils.FillText(self.TxtTime,localize("请先通关前置关卡"))
	end
end

function ActivityMountainMainLineNode:OnDestroy()
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
end

return ActivityMountainMainLineNode